mapper.select:
SELECT IATT_NO, SCATE_ID, SREF_TABLE, IREF_NO, SPATH, SNAME, SMAPPING, SEXT,
       SMETA, STITLE, SCONTENTS, ISEQ, SINS_DT, ISIZE, SSYS_ID, IDOWN_CNT
  FROM TB_ATTACH
 WHERE SREF_TABLE = #{refTable}
   AND IREF_NO    = #{refNo}
 ORDER BY ISEQ, IATT_NO

mapper.insert:
INSERT INTO TB_ATTACH (
	IATT_NO, SCATE_ID, SREF_TABLE, IREF_NO, SPATH, SNAME, SMAPPING, SEXT,
	SMETA, STITLE, SCONTENTS, ISEQ, SINS_DT, ISIZE
) VALUES (
	#{attNo}, #{cateId}, #{refTable}, #{refNo}, #{path}, #{name}, #{mapping}, #{ext},
	#{meta}, #{title}, #{contents}, #{seq},
	TO_CHAR(LOCALTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
	#{size}
)
